import os,glob,re,json
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
print(sorted(G))
for k in sorted(G): print(k, len(G[k]), len(G[k][0]))
inp=G['Demo pair 1 input']; out=G['Demo pair 1 output']
for r in range(10):
    print(''.join(map(str,inp[r])), '  ',''.join(map(str,out[r])))

from collections import deque
def solve(g):
    h,w=len(g),len(g[0]); bg=g[0][0]
    seen=[[False]*w for _ in range(h)]; out=[row[:] for row in g]
    for r in range(h):
        for c in range(w):
            if not seen[r][c] and g[r][c]!=bg:
                col=g[r][c]; q=deque([(r,c)]); seen[r][c]=True; rect=[]
                while q:
                    x,y=q.popleft(); rect.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<h and 0<=ny<w and not seen[nx][ny] and g[nx][ny]==col:
                            seen[nx][ny]=True; q.append((nx,ny))
                xs=[a for a,b in rect]; ys=[b for a,b in rect]
                r0,r1,c0,c1=min(xs),max(xs),min(ys),max(ys)
                interior=[(a,b) for a in range(r0+1,r1) for b in range(c0+1,c1) if g[a][b]==bg]
                fill=2 if (c1-c0+1)%2==0 else 7
                for a,b in interior: out[a][b]=fill
    return out
for k in ['Demo pair 1 input']:
    assert solve(G[k])==G[k+' output']
print(json.dumps(solve(G['Test input'])))

